window.VitanovaFinalPastQuestions = [{"id":"mss-final-paper-final-1","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-1","system":"MSS","exam":"Final","subject":"Theory","question":"A 56-year-old woman with diabetes has a thickened, yellow great toenail. Testing confirms dermatophyte onychomycosis. If oral treatment is indicated, which drug is preferred?","options":["Terbinafine","Griseofulvin","Nystatin","Ketoconazole"],"answer":0,"explanation":"Terbinafine reaches the nail and inhibits fungal squalene epoxidase. Griseofulvin takes longer and has poorer toenail cure rates. Nystatin is mainly used against Candida and lacks useful dermatophyte activity. Oral ketoconazole carries major liver toxicity and is unsuitable for nail infections."},{"id":"mss-final-paper-final-2","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-2","system":"MSS","exam":"Final","subject":"Theory","question":"Which finding characterizes piedra?","options":["Nodules attached to hair shafts","Pigmented patches on palms","Fine scale on the upper trunk","Broken hairs with scalp inflammation"],"answer":0,"explanation":"Black and white piedra produce concretions around hair shafts. Palmar pigmentation suggests tinea nigra. Fine trunk scale suggests pityriasis versicolor. Inflamed patches with broken hairs suggest tinea capitis."},{"id":"mss-final-paper-final-3","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-3","system":"MSS","exam":"Final","subject":"Theory","question":"Which species is the chigoe flea?","options":["Tunga penetrans","Pulex irritans","Xenopsylla cheopis","Ctenocephalides felis"],"answer":0,"explanation":"The female Tunga flea embeds in skin and causes tungiasis. Pulex irritans is the human flea. Xenopsylla cheopis is the oriental rat flea. Ctenocephalides felis is the cat flea."},{"id":"mss-final-paper-final-4","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-4","system":"MSS","exam":"Final","subject":"Theory","question":"Which artery and nerve travel together in the humeral radial groove?","options":["Deep brachial artery and radial nerve","Brachial artery and median nerve","Superior ulnar collateral artery and ulnar nerve","Posterior circumflex humeral artery and axillary nerve"],"answer":0,"explanation":"The profunda brachii accompanies the radial nerve around the posterior humerus. The brachial artery and median nerve course in the anterior arm. The ulnar nerve passes behind the medial epicondyle with its collateral artery. The axillary nerve and posterior circumflex humeral artery cross the quadrangular space."},{"id":"mss-final-paper-final-5","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-5","system":"MSS","exam":"Final","subject":"Theory","question":"What underlies a Heberden node?","options":["An osteophyte at a distal interphalangeal joint","An osteophyte at a proximal interphalangeal joint","A gouty tophus near a joint","A rheumatoid nodule over an extensor surface"],"answer":0,"explanation":"Heberden nodes reflect distal interphalangeal osteoarthritis. Proximal interphalangeal osteophytes form Bouchard nodes. Tophi are deposits of monosodium urate. Rheumatoid nodules are inflammatory lesions."},{"id":"mss-final-paper-final-6","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-6","system":"MSS","exam":"Final","subject":"Theory","question":"Which artery lies deep to the median cubital vein and can be injured during a deep venipuncture?","options":["Brachial artery","Radial artery","Ulnar artery","Deep brachial artery"],"answer":0,"explanation":"The brachial artery crosses the cubital fossa deep to the bicipital aponeurosis. The radial artery runs on the lateral forearm after bifurcation. The ulnar artery travels into the medial forearm. The deep brachial artery courses in the posterior arm."},{"id":"mss-final-paper-final-7","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-7","system":"MSS","exam":"Final","subject":"Theory","question":"Where is the dorsalis pedis pulse palpated relative to the extensor hallucis longus tendon?","options":["Just lateral to the tendon","Just medial to the tendon","Deep to the Achilles tendon","Behind the medial malleolus"],"answer":0,"explanation":"The vessel crosses the dorsum just lateral to extensor hallucis longus. The medial side is the opposite relation. The Achilles tendon is posterior to the ankle. The posterior tibial pulse is behind the medial malleolus."},{"id":"mss-final-paper-final-8","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-8","system":"MSS","exam":"Final","subject":"Theory","question":"Which structures traverse the quadrangular space?","options":["Axillary nerve and posterior circumflex humeral artery","Radial nerve and deep brachial artery","Circumflex scapular artery and accompanying veins","Suprascapular nerve and suprascapular artery"],"answer":0,"explanation":"The axillary bundle exits posteriorly through the quadrangular space. The radial nerve and profunda brachii cross the triangular interval. The circumflex scapular vessels cross the triangular space. The suprascapular bundle crosses the scapular notch region."},{"id":"mss-final-paper-final-9","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-9","system":"MSS","exam":"Final","subject":"Theory","question":"Which pair does not traverse the greater sciatic foramen?","options":["Femoral artery and femoral vein","Superior gluteal artery and nerve","Inferior gluteal artery and nerve","Internal pudendal artery and pudendal nerve"],"answer":0,"explanation":"The femoral vessels enter the thigh beneath the inguinal ligament. The superior gluteal bundle exits above piriformis. The inferior gluteal bundle exits below piriformis. The pudendal bundle exits below piriformis and reenters through the lesser foramen."},{"id":"mss-final-paper-final-10","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-10","system":"MSS","exam":"Final","subject":"Theory","question":"Which artery arises from the second part of the axillary artery?","options":["Lateral thoracic","Superior thoracic","Subscapular","Posterior circumflex humeral"],"answer":0,"explanation":"The lateral thoracic and thoracoacromial arteries typically arise behind pectoralis minor. Superior thoracic comes from the first part. Subscapular comes from the third part. Posterior circumflex humeral comes from the third part."},{"id":"mss-final-paper-final-11","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-11","system":"MSS","exam":"Final","subject":"Theory","question":"Which muscles make up triceps surae?","options":["Gastrocnemius and soleus","Gastrocnemius and plantaris","Soleus and tibialis posterior","Plantaris and popliteus"],"answer":0,"explanation":"Two gastrocnemius heads and soleus form the triceps surae. Plantaris is a separate superficial posterior muscle. Tibialis posterior is in the deep posterior compartment. Popliteus acts at the knee and is separate from the calf complex."},{"id":"mss-final-paper-final-12","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-12","system":"MSS","exam":"Final","subject":"Theory","question":"Which muscle is supplied by one named nerve?","options":["Brachioradialis","Brachialis","Adductor magnus","Flexor digitorum profundus"],"answer":0,"explanation":"Brachioradialis is supplied by the radial nerve. Brachialis typically receives musculocutaneous and radial contributions. Adductor magnus receives obturator and tibial sciatic contributions. Profundus receives anterior interosseous and ulnar branches."},{"id":"mss-final-paper-final-13","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-13","system":"MSS","exam":"Final","subject":"Theory","question":"Which nerve supplies sensation along the lateral border of the foot?","options":["Sural nerve","Saphenous nerve","Deep fibular nerve","Superficial fibular nerve"],"answer":0,"explanation":"The sural nerve supplies the lateral foot margin. The saphenous nerve supplies medial skin. The deep fibular nerve supplies the first web space. The superficial fibular nerve supplies most of the remaining dorsum."},{"id":"mss-final-paper-final-14","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-14","system":"MSS","exam":"Final","subject":"Theory","question":"Which conventional systemic agent can be administered orally for severe psoriasis?","options":["Methotrexate","Calcipotriol","Clobetasol","Adalimumab"],"answer":0,"explanation":"Methotrexate is a conventional systemic option available orally. Calcipotriol is a topical vitamin D analogue. Clobetasol is a topical corticosteroid. Adalimumab is an injectable biologic."},{"id":"mss-final-paper-final-15","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-15","system":"MSS","exam":"Final","subject":"Theory","question":"Which light is used with methoxsalen in PUVA therapy?","options":["Ultraviolet A","Ultraviolet B","Blue visible light","Infrared light"],"answer":0,"explanation":"PUVA combines a psoralen photosensitizer with UVA. Narrowband UVB is a separate phototherapy modality. Blue light has other dermatology applications. Infrared does not activate methoxsalen in PUVA."},{"id":"mss-final-paper-final-16","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-16","system":"MSS","exam":"Final","subject":"Theory","question":"Which condition is classically caused by Ancylostoma braziliense larvae in humans?","options":["Cutaneous larva migrans","Visceral larva migrans","Larva currens","Cutaneous leishmaniasis"],"answer":0,"explanation":"Dog and cat hookworm larvae migrate superficially in human skin. Visceral larva migrans is classically due to Toxocara. Larva currens is caused by Strongyloides. Cutaneous leishmaniasis is caused by Leishmania."},{"id":"mss-final-paper-final-17","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-17","system":"MSS","exam":"Final","subject":"Theory","question":"Which organism causes a subcutaneous rather than a superficial mycosis?","options":["Sporothrix schenckii","Piedraia hortae","Malassezia furfur","Hortaea werneckii"],"answer":0,"explanation":"Sporothrix is inoculated into the skin and can track along lymphatics. Piedraia causes black piedra on hair shafts. Malassezia causes pityriasis versicolor in the stratum corneum. Hortaea causes superficial tinea nigra."},{"id":"mss-final-paper-final-18","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-18","system":"MSS","exam":"Final","subject":"Theory","question":"What is the clinical result of reactivation of latent varicella-zoster virus?","options":["Herpes zoster","Primary varicella","Herpes labialis","Erythema infectiosum"],"answer":0,"explanation":"Reactivation in a sensory ganglion typically produces dermatomal shingles. Primary infection produces chickenpox. Herpes labialis is usually due to herpes simplex virus type 1. Erythema infectiosum is due to parvovirus B19."},{"id":"mss-final-paper-final-19","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-19","system":"MSS","exam":"Final","subject":"Theory","question":"Which finding or diagnosis is not attributable to measles?","options":["Roseola infantum","Koplik spots","Cough and coryza","Descending maculopapular rash"],"answer":0,"explanation":"Roseola infantum is usually due to human herpesvirus 6B. Koplik spots are characteristic of measles. Cough and coryza are typical prodromal findings. The measles rash typically starts on the face and spreads downward."},{"id":"mss-final-paper-final-20","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-20","system":"MSS","exam":"Final","subject":"Theory","question":"In which disorder are transient wheals the characteristic lesion?","options":["Urticaria","Plaque psoriasis","Tinea corporis","Pityriasis rosea"],"answer":0,"explanation":"Wheals reflect transient superficial dermal edema. Psoriasis forms persistent scaly plaques. Tinea corporis typically forms expanding annular plaques. Pityriasis rosea forms oval scaly patches."},{"id":"mss-final-paper-final-21","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-21","system":"MSS","exam":"Final","subject":"Theory","question":"Which skull finding can occur in advanced Paget disease of bone?","options":["Leontiasis ossea","Craniotabes","Premature suture fusion","Wormian bones"],"answer":0,"explanation":"Marked craniofacial overgrowth may cause leontiasis ossea. Craniotabes is softening of the infant skull. Premature suture fusion is craniosynostosis. Wormian bones are accessory sutural ossicles seen in several settings."},{"id":"mss-final-paper-final-22","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-22","system":"MSS","exam":"Final","subject":"Theory","question":"Which benign lesion typically forms a cartilage-capped outgrowth from the metaphysis near the knee?","options":["Osteochondroma","Enchondroma","Chondroblastoma","Giant cell tumor"],"answer":0,"explanation":"Osteochondroma is an exostosis continuous with the parent cortex and medulla. Enchondroma is typically intramedullary. Chondroblastoma usually arises in an epiphysis. Giant cell tumor often extends to a subarticular region after maturity."},{"id":"mss-final-paper-final-23","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-23","system":"MSS","exam":"Final","subject":"Theory","question":"Where does basal cell carcinoma most commonly occur?","options":["Sun-exposed facial skin","Palmar creases","Plantar surfaces","Oral mucosa"],"answer":0,"explanation":"The face is a common site because cumulative ultraviolet exposure contributes to risk. Palms are an unusual site. Plantar basal cell carcinoma is rare. Oral mucosa is an atypical site for cutaneous basal cell carcinoma."},{"id":"mss-final-paper-final-24","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-24","system":"MSS","exam":"Final","subject":"Theory","question":"Which statement about the inheritance of hypoparathyroidism is accurate?","options":["Inheritance varies with the underlying cause.","Familial cases all follow X-linked inheritance.","Acquired cases follow autosomal inheritance.","Familial cases all show recessive inheritance."],"answer":0,"explanation":"Hypoparathyroidism can be acquired or arise from different genetic disorders with different inheritance patterns. The recall does not name a subtype. Familial forms are also known with autosomal inheritance. Acquired hypoparathyroidism, for example after neck surgery, does not follow a Mendelian inheritance pattern. Some familial forms are autosomal dominant, including those due to activating CASR variants."},{"id":"mss-final-paper-final-25","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-25","system":"MSS","exam":"Final","subject":"Theory","question":"Which pattern can accompany vitamin D deficiency osteomalacia?","options":["Low phosphate and raised alkaline phosphatase","High phosphate and suppressed alkaline phosphatase","Low phosphate and suppressed alkaline phosphatase","High phosphate and raised alkaline phosphatase"],"answer":0,"explanation":"Secondary hyperparathyroidism can lower phosphate, while bone alkaline phosphatase rises. Urinary calcium is commonly low in nutritional deficiency, contrary to the recall. Suppressed alkaline phosphatase is atypical and high phosphate suggests another mechanism. Low phosphate fits, but alkaline phosphatase typically rises. Raised alkaline phosphatase fits, but phosphate is often low."},{"id":"mss-final-paper-final-26","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-26","system":"MSS","exam":"Final","subject":"Theory","question":"Which muscle receives both obturator and sciatic nerve innervation?","options":["Adductor magnus","Adductor longus","Gracilis","Semimembranosus"],"answer":0,"explanation":"The adductor portion receives obturator supply and the hamstring portion receives the tibial division of the sciatic nerve. Adductor longus is supplied by the obturator nerve. Gracilis is supplied by the obturator nerve. Semimembranosus is supplied by the tibial division of the sciatic nerve."},{"id":"mss-final-paper-final-27","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-27","system":"MSS","exam":"Final","subject":"Theory","question":"Which mechanism is incorrectly paired with its antifungal?","options":["Tolnaftate — inhibition of nucleic acid synthesis","Terbinafine — inhibition of squalene epoxidase","Fluconazole — inhibition of 14-alpha demethylase","Nystatin — binding to membrane ergosterol"],"answer":0,"explanation":"Tolnaftate inhibits squalene epoxidase. Terbinafine inhibits this enzyme in the ergosterol pathway. Fluconazole inhibits fungal lanosterol 14-alpha demethylase. Nystatin binds ergosterol and disrupts membrane integrity."},{"id":"mss-final-paper-final-28","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-28","system":"MSS","exam":"Final","subject":"Theory","question":"Which common primary malignant bone tumor produces osteoid directly from tumor cells?","options":["Osteosarcoma","Ewing sarcoma","Chondrosarcoma","Plasma cell myeloma"],"answer":0,"explanation":"Malignant osteoid is the defining histologic feature of osteosarcoma. Ewing sarcoma is a small round cell tumor. Chondrosarcoma produces malignant cartilage. Myeloma is a marrow plasma cell neoplasm. The revised stem avoids counting ambiguities."},{"id":"mss-final-paper-final-29","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-29","system":"MSS","exam":"Final","subject":"Theory","question":"Which fontanelle is at the junction of the sagittal and coronal sutures?","options":["Anterior","Posterior","Sphenoidal","Mastoid"],"answer":0,"explanation":"The anterior fontanelle corresponds to the region of bregma. The posterior fontanelle is at the sagittal–lambdoid junction. The sphenoidal fontanelle is anterolateral. The mastoid fontanelle is posterolateral."},{"id":"mss-final-paper-final-30","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-30","system":"MSS","exam":"Final","subject":"Theory","question":"Which upper limb change occurs toward the end of embryonic week 5?","options":["Formation of paddle-shaped hand plates","Separation of individual fingers","Formation of primary ossification centers","Completion of upper limb rotation"],"answer":0,"explanation":"The distal upper limb flattens into a hand plate. Interdigital tissue regresses later. Primary ossification in the limb occurs later. Upper limb rotation occurs later in development."},{"id":"mss-final-paper-final-32","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-32","system":"MSS","exam":"Final","subject":"Theory","question":"Which motion is chiefly produced by the middle fibers of deltoid between approximately 15° and 90°?","options":["Shoulder abduction","Shoulder adduction","Shoulder internal rotation","Shoulder external rotation"],"answer":0,"explanation":"Middle deltoid is a major abductor through this range. Pectoralis major and latissimus dorsi assist adduction. Subscapularis is a major internal rotator. Infraspinatus and teres minor are major external rotators."},{"id":"mss-final-paper-final-33","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-33","system":"MSS","exam":"Final","subject":"Theory","question":"What is the main embryonic origin of the frontal bone?","options":["Cranial neural crest","Paraxial mesoderm","Lateral plate mesoderm","Pharyngeal endoderm"],"answer":0,"explanation":"Cranial neural crest contributes to the frontal bone. Paraxial mesoderm contributes to bones including the parietal bone. Lateral plate mesoderm contributes to the appendicular skeleton. Pharyngeal endoderm lines the pouches and contributes to associated glands."},{"id":"mss-final-paper-final-34","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-34","system":"MSS","exam":"Final","subject":"Theory","question":"Which nerve primarily supplies the clavicular head of pectoralis major?","options":["Lateral pectoral nerve","Medial pectoral nerve","Long thoracic nerve","Thoracodorsal nerve"],"answer":0,"explanation":"The lateral pectoral nerve primarily supplies the clavicular head. The medial pectoral nerve supplies pectoralis minor and contributes to the sternocostal part of major. The long thoracic nerve supplies serratus anterior. The thoracodorsal nerve supplies latissimus dorsi."},{"id":"mss-final-paper-final-35","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-35","system":"MSS","exam":"Final","subject":"Theory","question":"What defines parakeratosis?","options":["Retained nuclei in the stratum corneum","Thickening of the spinous layer","Intercellular edema in the epidermis","Loss of cohesion between keratinocytes"],"answer":0,"explanation":"Cornified cells retain nuclei in parakeratosis. Spinous layer thickening is acanthosis. Intercellular edema is spongiosis. Loss of keratinocyte cohesion is acantholysis."},{"id":"mss-final-paper-final-Case 1","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-Case 1","system":"MSS","exam":"Final","subject":"Theory","question":"Which nail finding is most characteristic of psoriatic nail matrix involvement?","options":["Pitting","Koilonychia","Clubbing","Beau lines"],"answer":0,"explanation":"Focal abnormalities of the matrix cause small pits in the nail plate. Koilonychia means spoon-shaped nails. Clubbing changes the angle and contour of the digit. Beau lines are transverse grooves from interrupted growth."},{"id":"mss-final-paper-final-Case 2","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"final-Case 2","system":"MSS","exam":"Final","subject":"Theory","question":"What is the term for psoriasis predominantly affecting skin folds?","options":["Inverse psoriasis","Guttate psoriasis","Pustular psoriasis","Erythrodermic psoriasis"],"answer":0,"explanation":"Inverse psoriasis involves flexures and often has little scale. Guttate psoriasis presents as numerous small drop-like lesions. Pustular psoriasis features sterile pustules. Erythrodermic psoriasis involves extensive erythema and scaling."},{"id":"mss-final-paper-adrenaline-2","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-2","system":"MSS","exam":"Final","subject":"Theory","question":"Which embryonic structure gives rise to the nucleus pulposus?","options":["Notochord","Sclerotome","Dermatome","Myotome"],"answer":0,"explanation":"The nucleus pulposus is derived from the notochord. The sclerotome gives rise to vertebral structures and the annulus fibrosus. The dermatome contributes to dermis. The myotome gives rise to skeletal muscle."},{"id":"mss-final-paper-adrenaline-3","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-3","system":"MSS","exam":"Final","subject":"Theory","question":"What is the main embryonic origin of the petrous part of the temporal bone?","options":["Paraxial mesoderm","Cranial neural crest","Lateral plate mesoderm","Pharyngeal endoderm"],"answer":0,"explanation":"The petrous temporal bone develops from the cartilaginous otic capsule, principally from paraxial mesoderm. Neural crest contributes to multiple other cranial bones and regions. Lateral plate mesoderm contributes to the limb skeleton. Endoderm contributes to pharyngeal epithelial derivatives."},{"id":"mss-final-paper-adrenaline-4","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-4","system":"MSS","exam":"Final","subject":"Theory","question":"When do the hand plates first become apparent?","options":["Week 5","Week 4","Week 7","Week 9"],"answer":0,"explanation":"The distal upper limb flattens into a hand plate toward the end of week 5. The upper limb buds appear in week 4. By week 7 digital development has progressed beyond the initial hand plate. Week 9 occurs after the embryonic period."},{"id":"mss-final-paper-adrenaline-5","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-5","system":"MSS","exam":"Final","subject":"Theory","question":"What term describes abnormally short fingers or toes?","options":["Brachydactyly","Syndactyly","Polydactyly","Clinodactyly"],"answer":0,"explanation":"Brachydactyly refers to short digits. Syndactyly is fusion or webbing of digits. Polydactyly means extra digits. Clinodactyly means curvature of a digit."},{"id":"mss-final-paper-adrenaline-6a","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-6a","system":"MSS","exam":"Final","subject":"Theory","question":"Which ligament resists anterior translation of the tibia relative to the femur?","options":["Anterior cruciate","Posterior cruciate","Tibial collateral","Fibular collateral"],"answer":0,"explanation":"The anterior cruciate ligament restrains anterior tibial translation. The posterior cruciate ligament restrains posterior tibial translation. The tibial collateral ligament resists valgus force. The fibular collateral ligament resists varus force."},{"id":"mss-final-paper-adrenaline-6b","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-6b","system":"MSS","exam":"Final","subject":"Theory","question":"Which ligament runs from the posterior intercondylar tibia to the medial femoral condyle?","options":["Posterior cruciate","Anterior cruciate","Tibial collateral","Fibular collateral"],"answer":0,"explanation":"The posterior cruciate ligament has these attachments. The anterior cruciate connects anterior tibia to the lateral femoral condyle. The tibial collateral is on the medial aspect of the knee. The fibular collateral attaches to the fibular head."},{"id":"mss-final-paper-adrenaline-7","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-7","system":"MSS","exam":"Final","subject":"Theory","question":"Which neurovascular bundle exits the greater sciatic foramen above piriformis?","options":["Superior gluteal bundle","Inferior gluteal bundle","Internal pudendal bundle","Sciatic nerve and its companion vessels"],"answer":0,"explanation":"The superior gluteal bundle exits through the suprapiriform compartment. The inferior gluteal bundle exits below piriformis. The internal pudendal bundle exits below piriformis. The sciatic nerve typically passes below piriformis."},{"id":"mss-final-paper-adrenaline-8","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-8","system":"MSS","exam":"Final","subject":"Theory","question":"Which muscle is excluded from the short lateral rotator group at the hip?","options":["Gluteus minimus","Piriformis","Obturator internus","Quadratus femoris"],"answer":0,"explanation":"Gluteus minimus primarily abducts and assists medial rotation. Piriformis laterally rotates the extended hip. Obturator internus laterally rotates the hip. Quadratus femoris laterally rotates the hip."},{"id":"mss-final-paper-adrenaline-9","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-9","system":"MSS","exam":"Final","subject":"Theory","question":"The saphenous nerve is a cutaneous branch of which nerve?","options":["Femoral","Obturator","Tibial","Common fibular"],"answer":0,"explanation":"The saphenous is the terminal sensory branch of the femoral nerve. The obturator supplies medial thigh muscles and variable medial thigh skin. The tibial nerve supplies the posterior leg and plantar foot through its branches. The common fibular nerve branches supply the anterolateral leg."},{"id":"mss-final-paper-adrenaline-10a","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-10a","system":"MSS","exam":"Final","subject":"Theory","question":"Which spinal roots contribute to the femoral nerve?","options":["L2–L4","L1–L3","L3–L5","L4–S2"],"answer":0,"explanation":"The femoral nerve arises from posterior divisions of L2–L4 anterior rami. L1 is not part of the usual femoral contribution. L5 is not part of the usual contribution. Sacral roots do not contribute to the femoral nerve."},{"id":"mss-final-paper-adrenaline-10b","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-10b","system":"MSS","exam":"Final","subject":"Theory","question":"Where does the femoral nerve pass as it enters the thigh?","options":["Deep to the inguinal ligament and lateral to the artery","Inside the femoral sheath and medial to the vein","Through the obturator canal and medial to the artery","Through the greater sciatic foramen and posterior to the artery"],"answer":0,"explanation":"It enters below the inguinal ligament outside the femoral sheath, lateral to the artery. It lies outside the sheath. The obturator nerve uses the obturator canal. The sciatic nerve uses the greater sciatic foramen."},{"id":"mss-final-paper-adrenaline-11","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-11","system":"MSS","exam":"Final","subject":"Theory","question":"What skin region is supplied by the lateral femoral cutaneous nerve?","options":["Anterolateral thigh","Medial lower leg","Posterior thigh","First dorsal web space"],"answer":0,"explanation":"This sensory nerve supplies the anterolateral thigh. The saphenous nerve supplies medial lower-leg skin. The posterior femoral cutaneous nerve supplies posterior thigh skin. The deep fibular nerve supplies the first dorsal web space."},{"id":"mss-final-paper-adrenaline-12","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-12","system":"MSS","exam":"Final","subject":"Theory","question":"Which lumbar plexus nerve emerges through the anterior surface of psoas major?","options":["Genitofemoral","Femoral","Obturator","Lateral femoral cutaneous"],"answer":0,"explanation":"The genitofemoral nerve pierces psoas major anteriorly. The femoral nerve emerges from its lateral border. The obturator emerges from its medial border. The lateral femoral cutaneous nerve emerges laterally."},{"id":"mss-final-paper-adrenaline-13","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-13","system":"MSS","exam":"Final","subject":"Theory","question":"Which statement about the popliteal fossa is incorrect?","options":["The popliteal vein is the most superficial of the central bundle.","The popliteal artery is deepest in the central bundle.","The tibial nerve lies superficial to the popliteal vein.","The small saphenous vein usually drains into the popliteal vein."],"answer":0,"explanation":"The tibial nerve is the most superficial element in the central bundle. The artery is deepest and lies near the floor. The tibial nerve is superficial to the vein. The small saphenous commonly drains into the popliteal vein."},{"id":"mss-final-paper-adrenaline-14","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-14","system":"MSS","exam":"Final","subject":"Theory","question":"What muscle forms the triceps surae together with the two gastrocnemius heads?","options":["Soleus","Plantaris","Popliteus","Tibialis posterior"],"answer":0,"explanation":"Soleus and gastrocnemius contribute to the calcaneal tendon and make up triceps surae. Plantaris is a separate muscle with a thin tendon. Popliteus acts across the knee. Tibialis posterior belongs to the deep posterior leg."},{"id":"mss-final-paper-adrenaline-15","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-15","system":"MSS","exam":"Final","subject":"Theory","question":"Which nerve accompanies the great saphenous vein along the medial lower leg?","options":["Saphenous","Sural","Deep fibular","Superficial fibular"],"answer":0,"explanation":"The saphenous nerve travels with or near the great saphenous vein in the medial leg. The sural nerve is associated with the small saphenous vein. The deep fibular nerve travels in the anterior compartment. The superficial fibular nerve courses in the lateral compartment."},{"id":"mss-final-paper-adrenaline-16","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-16","system":"MSS","exam":"Final","subject":"Theory","question":"Which tendon does not pass beneath the ankle's extensor retinacula?","options":["Flexor hallucis longus","Extensor hallucis longus","Tibialis anterior","Extensor digitorum longus"],"answer":0,"explanation":"Flexor hallucis longus runs behind the medial malleolus beneath the flexor retinaculum. Extensor hallucis longus passes on the anterior ankle beneath extensor retinacula. Tibialis anterior passes deep to the extensor retinacula. Extensor digitorum longus crosses the ankle under the extensor retinacula."},{"id":"mss-final-paper-adrenaline-17","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-17","system":"MSS","exam":"Final","subject":"Theory","question":"Where should you palpate the dorsalis pedis artery relative to the extensor hallucis longus tendon?","options":["Immediately lateral","Immediately medial","Behind the medial malleolus","Behind the lateral malleolus"],"answer":0,"explanation":"Palpate on the dorsum lateral to the tendon. The medial relation reverses the anatomy. Behind the medial malleolus is the posterior tibial pulse. The lateral malleolus lies away from the usual dorsalis pedis pulse point."},{"id":"mss-final-paper-adrenaline-18","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-18","system":"MSS","exam":"Final","subject":"Theory","question":"A fibular-neck fracture causes loss of dorsiflexion. Which nerve injury and deformity best fit?","options":["Common fibular lesion with equinovarus","Tibial lesion with equinovarus","Sural lesion with equinovarus","Femoral lesion with equinovarus"],"answer":0,"explanation":"Loss of anterior and lateral compartment function causes foot drop with unopposed plantarflexion and inversion. A tibial lesion weakens plantarflexion. The sural nerve is sensory. A femoral lesion chiefly weakens knee extension."},{"id":"mss-final-paper-adrenaline-19","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-19","system":"MSS","exam":"Final","subject":"Theory","question":"Which part of the thigh adductor group retains direct sciatic innervation after an obturator lesion?","options":["Hamstring portion of adductor magnus","Adductor portion of adductor magnus","Adductor longus","Gracilis"],"answer":0,"explanation":"The tibial division of the sciatic nerve supplies the hamstring portion. The adductor portion receives the obturator nerve. Adductor longus is obturator-innervated. Gracilis is obturator-innervated."},{"id":"mss-final-paper-adrenaline-20","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-20","system":"MSS","exam":"Final","subject":"Theory","question":"Which structure lies directly lateral to the femoral artery just below the inguinal ligament?","options":["Femoral nerve","Femoral vein","Femoral canal","Deep inguinal lymph node"],"answer":0,"explanation":"The femoral nerve lies lateral to the artery and outside the sheath. The vein is medial to the artery at this level. The femoral canal lies medial to the vein. Deep inguinal nodes are associated with the medial lymphatic compartment."},{"id":"mss-final-paper-adrenaline-21","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-21","system":"MSS","exam":"Final","subject":"Theory","question":"Which muscle forms the medial boundary of the femoral triangle?","options":["Adductor longus","Sartorius","Pectineus","Iliopsoas"],"answer":0,"explanation":"The medial border of adductor longus forms its medial boundary. Sartorius forms the lateral boundary. Pectineus contributes to the floor. Iliopsoas contributes to the floor."},{"id":"mss-final-paper-adrenaline-22","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-22","system":"MSS","exam":"Final","subject":"Theory","question":"Which hand posture classically follows an ulnar nerve injury at the wrist?","options":["Clawing of digits 4 and 5","Clawing of digits 2 and 3","Wrist drop","Loss of index finger flexion alone"],"answer":0,"explanation":"Loss of the medial lumbricals and other intrinsic muscles favors MCP extension and IP flexion in digits 4–5. The lateral lumbricals are supplied by the median nerve. Wrist drop suggests radial motor dysfunction. Isolated weakness of index distal flexion points to median or anterior interosseous dysfunction."},{"id":"mss-final-paper-adrenaline-23","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-23","system":"MSS","exam":"Final","subject":"Theory","question":"A patient has recurrent itchy scaly patches and a family history of asthma and allergic rhinitis. What is most likely?","options":["Atopic dermatitis","Plaque psoriasis","Tinea corporis","Allergic contact dermatitis"],"answer":0,"explanation":"The itchy eczema plus atopic history supports atopic dermatitis. Psoriasis typically has sharply demarcated plaques with scale. Tinea corporis usually has a scaly advancing border. Allergic contact dermatitis follows sensitization and exposure, often with a matching distribution."},{"id":"mss-final-paper-adrenaline-24","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-24","system":"MSS","exam":"Final","subject":"Theory","question":"Nail pitting, thickening and separation of the nail plate from the bed can be features of which disorder?","options":["Psoriasis","Urticaria","Vitiligo","Basal cell carcinoma"],"answer":0,"explanation":"Psoriatic inflammation of the matrix produces pitting and nail-bed disease can produce onycholysis. Urticaria produces transient wheals. Vitiligo produces depigmented macules and patches. Basal cell carcinoma usually produces a localized skin tumor."},{"id":"mss-final-paper-adrenaline-25","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-25","system":"MSS","exam":"Final","subject":"Theory","question":"Which diagnosis fits atypical basal keratinocytes and epidermal dysplasia in a rough sun-exposed lesion?","options":["Actinic keratosis","Seborrheic keratosis","Dermatofibroma","Melanocytic nevus"],"answer":0,"explanation":"Chronic ultraviolet damage produces keratinocyte atypia in actinic keratosis. Seborrheic keratosis typically shows benign epidermal proliferation and horn cysts. Dermatofibroma is a dermal spindle cell lesion. A nevus is a melanocytic proliferation."},{"id":"mss-final-paper-adrenaline-26","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-26","system":"MSS","exam":"Final","subject":"Theory","question":"Which finding is least characteristic of cutaneous melanoma?","options":["A smooth regular border","Asymmetry across the lesion","Several colors in one lesion","Recent change in appearance"],"answer":0,"explanation":"A smooth regular border is less typical than border irregularity. Asymmetry is an ABCDE warning feature. Variegated color is a warning feature. Evolution in size, shape, or color is a warning feature."},{"id":"mss-final-paper-adrenaline-27","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-27","system":"MSS","exam":"Final","subject":"Theory","question":"Which malignant bone tumor is defined by formation of osteoid by tumor cells?","options":["Osteosarcoma","Chondrosarcoma","Ewing sarcoma","Plasma cell myeloma"],"answer":0,"explanation":"Malignant osteoid identifies osteosarcoma. Chondrosarcoma forms malignant cartilage. Ewing sarcoma is a small round cell tumor. Myeloma is a plasma cell neoplasm."},{"id":"mss-final-paper-adrenaline-28","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-28","system":"MSS","exam":"Final","subject":"Theory","question":"A femoral diaphyseal tumor has t(11;22)(q24;q12). What is most likely?","options":["Ewing sarcoma","Osteosarcoma","Chondrosarcoma","Osteochondroma"],"answer":0,"explanation":"This translocation usually creates the EWSR1–FLI1 fusion typical of Ewing sarcoma. Osteosarcoma is identified by malignant osteoid. Chondrosarcoma produces malignant cartilage. Osteochondroma is a benign cartilage-capped exostosis."},{"id":"mss-final-paper-adrenaline-29","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-29","system":"MSS","exam":"Final","subject":"Theory","question":"Which myopathy classically shows myofibers with rimmed vacuoles and intracellular protein aggregates?","options":["Inclusion body myositis","Dermatomyositis","Immune-mediated necrotizing myopathy","Glucocorticoid-induced myopathy"],"answer":0,"explanation":"Rimmed vacuoles and protein aggregates are characteristic in inclusion body myositis. Dermatomyositis classically shows perifascicular atrophy. Necrotizing myopathy shows prominent myofiber necrosis and regeneration. Glucocorticoid myopathy commonly shows type II fiber atrophy."},{"id":"mss-final-paper-adrenaline-30","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-30","system":"MSS","exam":"Final","subject":"Theory","question":"Which process does not itself explain post-exercise oxygen consumption above baseline?","options":["Increased glycolytic flux","Phosphocreatine restoration","Reoxygenation of myoglobin","Persistently elevated body temperature"],"answer":0,"explanation":"High glycolytic flux during exercise is distinct from mechanisms sustaining aerobic recovery demand. Phosphocreatine recovery is supported by aerobic ATP production. Myoglobin reoxygenation contributes to early recovery. Elevated temperature can sustain increased metabolic demand."},{"id":"mss-final-paper-adrenaline-31","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-31","system":"MSS","exam":"Final","subject":"Theory","question":"Which change promotes a shift toward mitochondrial fatty acid oxidation?","options":["Decreased malonyl-CoA","Increased malonyl-CoA","Decreased carnitine availability","Decreased CPT1 activity"],"answer":0,"explanation":"Reducing malonyl-CoA releases inhibition of carnitine palmitoyltransferase 1 (CPT1). Malonyl-CoA inhibits CPT1. Carnitine is needed for long-chain fatty acid transport. Lower CPT1 activity decreases mitochondrial fatty acid entry."},{"id":"mss-final-paper-adrenaline-32","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-32","system":"MSS","exam":"Final","subject":"Theory","question":"Which signals support osteoclast differentiation and survival?","options":["RANKL and M-CSF","Osteoprotegerin and calcitonin","Calcitonin and sclerostin","Osteoprotegerin and sclerostin"],"answer":0,"explanation":"RANK ligand drives osteoclast differentiation and macrophage colony-stimulating factor supports precursor survival. Osteoprotegerin intercepts RANKL and calcitonin inhibits osteoclast activity. Calcitonin inhibits osteoclasts and sclerostin mainly inhibits bone formation. Neither is the principal positive signal pair."},{"id":"mss-final-paper-adrenaline-33","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-33","system":"MSS","exam":"Final","subject":"Theory","question":"Which vitamin is required for gamma-carboxylation of osteocalcin?","options":["Vitamin K","Vitamin C","Vitamin D","Vitamin A"],"answer":0,"explanation":"Vitamin K is the cofactor for gamma-glutamyl carboxylation of osteocalcin. Vitamin C supports collagen hydroxylation. Vitamin D can regulate osteocalcin expression and mineral homeostasis. Vitamin A does not serve as the carboxylase cofactor."},{"id":"mss-final-paper-adrenaline-34","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-34","system":"MSS","exam":"Final","subject":"Theory","question":"Which virus classically causes a slapped-cheek rash in children?","options":["Parvovirus B19","Human herpesvirus 6","Measles virus","Rubella virus"],"answer":0,"explanation":"Parvovirus B19 causes erythema infectiosum with cheek erythema. Human herpesvirus 6 causes roseola. Measles usually features cough, coryza and conjunctivitis. Rubella can feature posterior auricular and suboccipital lymphadenopathy."},{"id":"mss-final-paper-adrenaline-35","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-35","system":"MSS","exam":"Final","subject":"Theory","question":"Which rash finding classically distinguishes chickenpox from a synchronous vesicular eruption?","options":["Lesions at several stages at the same time","All lesions crust at the same time","Vesicles limited to a single dermatome","A uniform eruption of nonblanching petechiae"],"answer":0,"explanation":"Successive crops of chickenpox produce macules, papules, vesicles and crusts together. Uniform staging contrasts with the classic crops. A single dermatome suggests herpes zoster. Petechiae do not describe the typical varicella eruption."},{"id":"mss-final-paper-adrenaline-36","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-36","system":"MSS","exam":"Final","subject":"Theory","question":"Which pairing describes the main forms of Leishmania in its mammalian and sand fly hosts?","options":["Amastigotes in macrophages and promastigotes in the sand fly","Promastigotes in macrophages and amastigotes in the sand fly","Amastigotes in erythrocytes and promastigotes in the sand fly","Epimastigotes in macrophages and amastigotes in the sand fly"],"answer":0,"explanation":"Intracellular amastigotes multiply in mammalian phagocytes and promastigotes develop in the fly. This reverses the main stages. The mammalian stage is in phagocytes. Epimastigotes are associated with Trypanosoma cruzi."},{"id":"mss-final-paper-adrenaline-37","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-37","system":"MSS","exam":"Final","subject":"Theory","question":"Which organism that causes lymphocutaneous infection typically grows as mold near 25°C and yeast at 37°C?","options":["Sporothrix schenckii","Piedraia hortae","Trichophyton rubrum","Malassezia furfur"],"answer":0,"explanation":"Sporothrix is thermally dimorphic and commonly produces nodules along draining lymphatics. Piedraia causes black piedra on hairs. Trichophyton is a dermatophyte and lacks this usual temperature-dependent yeast transition. Malassezia causes superficial conditions such as pityriasis versicolor."},{"id":"mss-final-paper-adrenaline-38","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-38","system":"MSS","exam":"Final","subject":"Theory","question":"Which presentation best fits cutaneous larva migrans?","options":["An itchy serpiginous track after barefoot beach exposure","A painless nodule progressing along a lymphatic chain","A rapidly recurring perianal wheal that migrates within hours","A shallow ulcer with a raised indurated margin"],"answer":0,"explanation":"Dog or cat hookworm larvae migrate slowly through superficial human skin. Lymphatic nodules suggest sporotrichosis. Rapid migration can occur with Strongyloides larva currens. A chronic raised-edge ulcer can occur with cutaneous leishmaniasis."},{"id":"mss-final-paper-adrenaline-39","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-39","system":"MSS","exam":"Final","subject":"Theory","question":"What chronic infection can cause draining sinuses with black grains from the foot?","options":["Eumycetoma","Actinomycosis","Cutaneous leishmaniasis","Lymphocutaneous sporotrichosis"],"answer":0,"explanation":"Fungal mycetoma, for example due to Madurella mycetomatis, can produce black grains. Actinomycosis can produce yellow sulfur granules. Cutaneous leishmaniasis can cause a chronic ulcer without characteristic grains. Sporotrichosis commonly causes nodules along lymphatics."},{"id":"mss-final-paper-adrenaline-40","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-40","system":"MSS","exam":"Final","subject":"Theory","question":"In hair restoration, what does PRP refer to?","options":["Platelet-rich plasma prepared from autologous blood","Platelet-poor plasma prepared from autologous blood","Plasma separated from pooled donor blood","Packed erythrocytes prepared from autologous blood"],"answer":0,"explanation":"PRP concentrates a person's platelets in a plasma preparation. Platelet-poor plasma has a depleted platelet fraction. Donor plasma is not the usual source of PRP for this use. Packed erythrocytes are enriched in red cells."},{"id":"mss-final-paper-adrenaline-41","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-41","system":"MSS","exam":"Final","subject":"Theory","question":"Which action is associated with minoxidil in hair follicles?","options":["Opening ATP-sensitive potassium channels","Blocking androgen receptors in the follicle","Inhibiting type II 5-alpha reductase","Inhibiting prostaglandin synthesis"],"answer":0,"explanation":"Minoxidil sulfate opens ATP-sensitive potassium channels. Minoxidil can prolong anagen, although its hair growth mechanism is incompletely understood. Direct androgen receptor blockade is associated with drugs such as spironolactone. Finasteride inhibits type II 5-alpha reductase. Cyclooxygenase inhibitors reduce prostaglandin synthesis."},{"id":"mss-final-paper-adrenaline-42","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-42","system":"MSS","exam":"Final","subject":"Theory","question":"Which adverse effect is associated with oral isotretinoin?","options":["Hypertriglyceridemia","Severe hypoglycemia","Hyperprolactinemia","Persistent hypocalcemia"],"answer":0,"explanation":"Isotretinoin may elevate triglycerides and is also teratogenic. Severe hypoglycemia is not a characteristic effect. Elevated prolactin is not a characteristic effect. Persistent hypocalcemia is not typical."},{"id":"mss-final-paper-adrenaline-43","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-43","system":"MSS","exam":"Final","subject":"Theory","question":"Which statement about topical retinoids for acne is incorrect?","options":["They are the principal direct bactericidal agents against Cutibacterium acnes.","They help normalize keratinization in the follicle.","They can cause local irritation and peeling.","They help prevent formation of microcomedones."],"answer":0,"explanation":"Benzoyl peroxide provides direct oxidative killing of C. acnes. Retinoids mainly alter follicular keratinization. Normalization of follicular keratinization is a core retinoid effect. Dryness, irritation and peeling are common local effects. Retinoids reduce microcomedone formation by altering follicular epithelial differentiation."},{"id":"mss-final-paper-adrenaline-44","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-44","system":"MSS","exam":"Final","subject":"Theory","question":"Which neuromuscular blocker typically produces fasciculations followed by flaccid paralysis?","options":["Succinylcholine","Rocuronium","Vecuronium","Cisatracurium"],"answer":0,"explanation":"Succinylcholine activates muscle nicotinic receptors and then maintains depolarizing blockade. Rocuronium is a competitive nondepolarizing blocker. Vecuronium is a competitive nondepolarizing blocker. Cisatracurium is a competitive nondepolarizing blocker."},{"id":"mss-final-paper-adrenaline-45b","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-45b","system":"MSS","exam":"Final","subject":"Theory","question":"What is the principal receptor target of ketamine in its dissociative anesthetic action?","options":["NMDA receptor","GABA-A receptor","Muscarinic receptor","Glycine receptor"],"answer":0,"explanation":"Ketamine acts mainly as a noncompetitive NMDA receptor antagonist. The scan has GABAergic wording marked out. GABA-A potentiation is characteristic of anesthetics such as propofol. Muscarinic blockade is characteristic of drugs such as atropine. Glycine receptors are inhibitory chloride channels and are not ketamine's principal target."},{"id":"mss-final-paper-adrenaline-46a","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-46a","system":"MSS","exam":"Final","subject":"Theory","question":"What type of peripheral nerve ending usually detects painful stimuli?","options":["Free nerve endings","Pacinian corpuscles","Meissner corpuscles","Merkel cell complexes"],"answer":0,"explanation":"Nociceptors typically have free peripheral endings. Pacinian corpuscles detect vibration and deep pressure. Meissner corpuscles detect light touch and low-frequency vibration. Merkel complexes detect sustained light touch and texture."},{"id":"mss-final-paper-adrenaline-46b","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"adrenaline-46b","system":"MSS","exam":"Final","subject":"Theory","question":"Which fibers typically carry the fast, sharp first pain from a noxious mechanical or thermal stimulus?","options":["A-delta fibers","C fibers","A-beta fibers","A-alpha fibers"],"answer":0,"explanation":"Thinly myelinated A-delta fibers conduct fast first pain. Unmyelinated C fibers typically carry slower second pain. A-beta fibers mainly convey low-threshold touch. A-alpha fibers include fast proprioceptive and motor fibers."},{"id":"mss-final-paper-lab-2","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-2","system":"MSS","exam":"Final","subject":"Practical","question":"A 70-year-old man sustains a hip fracture without reported trauma. Which underlying condition commonly predisposes to this type of fragility fracture?","options":["Osteoporosis","Osteopetrosis","Osteochondroma","Osteomyelitis"],"answer":0,"explanation":"Osteoporosis reduces bone strength and predisposes older adults to low-trauma hip fractures. Osteopetrosis can cause brittle bones but is much less common and has increased radiographic density. Osteochondroma is a localized benign cartilage-capped outgrowth. Osteomyelitis is infection of bone, which requires additional supporting findings.","labImage":"figure-2.jpg"},{"id":"mss-final-paper-lab-3","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-3","system":"MSS","exam":"Final","subject":"Practical","question":"Which pair of muscle biopsy findings supports denervation followed by reinnervation?","options":["Grouped atrophy and fiber-type grouping","Perifascicular atrophy and capillary injury","Rimmed vacuoles and protein aggregates","Myofiber necrosis and sparse inflammation"],"answer":0,"explanation":"Grouped atrophy reflects denervation and fiber-type grouping reflects collateral reinnervation. Perifascicular atrophy points toward dermatomyositis. Rimmed vacuoles suggest inclusion body myositis. Prominent necrosis with sparse inflammation suggests necrotizing myopathy.","labImage":"figure-3.jpg"},{"id":"mss-final-paper-lab-4","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-4","system":"MSS","exam":"Final","subject":"Practical","question":"Which histologic finding is expected in a conventional lipoma?","options":["Mature adipocytes resembling normal fat","Pleomorphic spindle cells with atypical mitoses","Lobules of cartilage with chondrocytes","Vascular spaces lined by endothelial cells"],"answer":0,"explanation":"A conventional lipoma consists of uniform mature adipocytes. Pleomorphic mitotically active spindle cells raise concern for malignancy. Cartilage lobules are characteristic of a cartilaginous lesion. Endothelial-lined vascular spaces suggest a vascular lesion.","labImage":"figure-4.jpg"},{"id":"mss-final-paper-lab-5","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-5","system":"MSS","exam":"Final","subject":"Practical","question":"What term describes the raw linear skin defect shown on the forearm?","options":["Excoriation","Lichenification","Fissure","Wheal"],"answer":0,"explanation":"An excoriation is a scratch-induced superficial loss of skin. Lichenification is thickening with accentuated skin lines. A fissure is a linear crack that can extend into the dermis. A wheal is a transient raised area caused by edema.","labImage":"figure-5.jpg"},{"id":"mss-final-paper-lab-6","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-6","system":"MSS","exam":"Final","subject":"Practical","question":"Which skull space is marked by the arrow?","options":["Pterygopalatine fossa","Infratemporal fossa","Temporal fossa","Middle cranial fossa"],"answer":0,"explanation":"The narrow space behind the maxilla at the arrow is the pterygopalatine fossa. The infratemporal fossa is lateral to it. The temporal fossa lies above the zygomatic arch. The middle cranial fossa is intracranial.","labImage":"figure-6.jpg"},{"id":"mss-final-paper-lab-7","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-7","system":"MSS","exam":"Final","subject":"Practical","question":"Which label marks the channel for the internal carotid artery?","options":["D","A","B","C"],"answer":0,"explanation":"The recall identifies D as the carotid canal through the petrous temporal bone. A points to another skull-base opening. B points to another skull-base opening. C lies posterior to the carotid canal and marks another opening.","labImage":"figure-7.jpg"},{"id":"mss-final-paper-lab-8","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-8","system":"MSS","exam":"Final","subject":"Practical","question":"Which numbered label identifies iliocostalis lumborum?","options":["5","2","3","4"],"answer":0,"explanation":"The recall marks 5 on the caudal lateral erector spinae column. Label 2 is positioned more medially. Label 3 is at a higher level in the specimen. Label 4 points more medially than the marked lumborum region.","labImage":"figure-8.jpg"},{"id":"mss-final-paper-lab-9","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-9","system":"MSS","exam":"Final","subject":"Practical","question":"Which labeled muscle is the exception to hip extension in the displayed group?","options":["4","1","2","3"],"answer":0,"explanation":"The recalled key identifies 4 as the exception. The short head of biceps femoris illustrates the principle that a muscle must cross the hip to extend it. The supplied scan key includes 1 among the extensors. The supplied scan key includes 2 among the extensors. The supplied scan key includes 3 among the extensors.","labImage":"figure-9.jpg"},{"id":"mss-final-paper-lab-10","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-10","system":"MSS","exam":"Final","subject":"Practical","question":"Which label-and-structure pairing is correct in the gluteal dissection?","options":["1 — piriformis","1 — obturator internus","1 — quadratus femoris","1 — gluteus medius"],"answer":0,"explanation":"The recall identifies label 1 as piriformis. Obturator internus lies inferior to piriformis. Quadratus femoris lies inferior to the gemelli. Gluteus medius lies more superiorly.","labImage":"figure-10.jpg"},{"id":"mss-final-paper-lab-11","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-11","system":"MSS","exam":"Final","subject":"Practical","question":"Which muscle is labeled 4 in the anterior leg image?","options":["Fibularis tertius","Tibialis anterior","Extensor hallucis longus","Extensor digitorum longus"],"answer":0,"explanation":"The recall identifies label 4 as fibularis tertius, which inserts on the base of the fifth metatarsal. Tibialis anterior inserts medially on the foot. Extensor hallucis longus goes to the great toe. Extensor digitorum longus extends toes two through five.","labImage":"figure-11.jpg"},{"id":"mss-final-paper-lab-12","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-12","system":"MSS","exam":"Final","subject":"Practical","question":"Identify the marked muscle in the forearm dissection.","options":["Brachioradialis","Extensor carpi radialis longus","Extensor carpi radialis brevis","Extensor digitorum"],"answer":0,"explanation":"The marked superficial lateral forearm muscle is brachioradialis, which inserts near the radial styloid. Extensor carpi radialis longus inserts at the second metacarpal base. Extensor carpi radialis brevis inserts at the third metacarpal base. Extensor digitorum sends tendons to the extensor expansions of digits two through five.","labImage":"figure-12.jpg"},{"id":"mss-final-paper-lab-13","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-13","system":"MSS","exam":"Final","subject":"Practical","question":"Which tendon marks the medial border of the anatomical snuffbox in the image?","options":["Extensor pollicis longus","Extensor pollicis brevis","Abductor pollicis longus","Extensor indicis"],"answer":0,"explanation":"The extensor pollicis longus forms the medial border after passing around the dorsal radial tubercle. Extensor pollicis brevis contributes to the lateral border. Abductor pollicis longus contributes to the lateral border. Extensor indicis goes to the index finger and does not border the snuffbox.","labImage":"figure-13.jpg"},{"id":"mss-final-paper-lab-14a","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-14a","system":"MSS","exam":"Final","subject":"Practical","question":"Which nerve supplies the marked flexor digiti minimi brevis in the hand specimen?","options":["Deep branch of ulnar nerve","Superficial branch of ulnar nerve","Recurrent branch of median nerve","Deep branch of radial nerve"],"answer":0,"explanation":"The deep ulnar branch supplies the hypothenar muscles including flexor digiti minimi brevis. The superficial ulnar branch is largely sensory and supplies palmaris brevis. The recurrent median branch supplies several thenar muscles. The deep radial branch supplies muscles of the posterior forearm.","labImage":"figure-14a.jpg"},{"id":"mss-final-paper-lab-14b","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-14b","system":"MSS","exam":"Final","subject":"Practical","question":"Identify the marked thenar muscle labeled 2.","options":["Abductor pollicis brevis","Flexor pollicis brevis","Opponens pollicis","Adductor pollicis"],"answer":0,"explanation":"Label 2 identifies the superficial abductor pollicis brevis in the recall figure. Flexor pollicis brevis is labeled separately. Opponens pollicis lies deeper. Adductor pollicis lies deeper and more medially in the palm.","labImage":"figure-14b.jpg"},{"id":"mss-final-paper-lab-15","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-15","system":"MSS","exam":"Final","subject":"Practical","question":"What displacement is primarily resisted by the marked knee ligament?","options":["Anterior translation of the tibia","Posterior translation of the tibia","Medial gapping during valgus stress","Lateral gapping during varus stress"],"answer":0,"explanation":"The marked anterior cruciate ligament restrains anterior tibial translation. The posterior cruciate ligament chiefly restrains posterior translation. The tibial collateral ligament resists medial opening with valgus. The fibular collateral ligament resists lateral opening with varus.","labImage":"figure-15.jpg"},{"id":"mss-final-paper-lab-16","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-16","system":"MSS","exam":"Final","subject":"Practical","question":"Which numbered point marks the insertion of teres major?","options":["3","1","2","4"],"answer":0,"explanation":"The supplied key marks 3, at the medial lip of the intertubercular sulcus. Label 1 is not at the medial lip. Label 2 is not the attachment identified by the recall. Label 4 is not the marked medial lip.","labImage":"figure-16.jpg"},{"id":"mss-final-paper-lab-17","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-17","system":"MSS","exam":"Final","subject":"Practical","question":"Which ligament component is especially important in resisting anterior shoulder dislocation in abduction and external rotation?","options":["Anterior band of the inferior glenohumeral ligament","Posterior band of the inferior glenohumeral ligament","Coracoacromial ligament","Coracoclavicular ligament"],"answer":0,"explanation":"The anterior band is a primary passive restraint in this position and can be injured during anterior dislocation. The posterior band primarily helps restrain posterior translation in appropriate positions. The coracoacromial ligament forms the arch above the humeral head. The coracoclavicular ligament stabilizes the clavicle relative to the scapula.","labImage":"figure-17.jpg"},{"id":"mss-final-paper-lab-18","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-18","system":"MSS","exam":"Final","subject":"Practical","question":"Which enzyme deficiency can cause a form of osteopetrosis by impairing osteoclast acidification?","options":["Carbonic anhydrase II","Alkaline phosphatase","Lysyl hydroxylase","Tissue transglutaminase"],"answer":0,"explanation":"Carbonic anhydrase II generates protons that support acidification of the osteoclast resorption compartment. Its deficiency can cause osteopetrosis with renal tubular acidosis. Tissue-nonspecific alkaline phosphatase deficiency causes hypophosphatasia. Lysyl hydroxylase deficiency affects collagen maturation. Tissue transglutaminase does not supply protons for osteoclast resorption."},{"id":"mss-final-paper-lab-19","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-19","system":"MSS","exam":"Final","subject":"Practical","question":"An oxidase-positive bacterium with a fruity odor suggests Pseudomonas aeruginosa. How does it appear on MacConkey agar?","options":["Colorless colonies","Pink colonies","Black-centered colonies","Green metallic sheen"],"answer":0,"explanation":"Pseudomonas is a non-lactose fermenter and forms colorless colonies on MacConkey agar. Pink suggests acid production from lactose fermentation. Black centers indicate hydrogen sulfide on some other media. A metallic sheen is associated with strong lactose fermentation on eosin methylene blue agar."},{"id":"mss-final-paper-lab-20","kind":"final-past-paper","lectureId":"past-mss-final","quizId":"lab-20","system":"MSS","exam":"Final","subject":"Practical","question":"A septic arthritis aspirate shows Gram-positive cocci in clusters. Which test helps identify Staphylococcus aureus among staphylococci?","options":["Coagulase","Catalase","Optochin susceptibility","Bile esculin hydrolysis"],"answer":0,"explanation":"S. aureus is usually coagulase positive and most other staphylococci are coagulase negative. Catalase differentiates staphylococci from streptococci but most staphylococci are catalase positive. Optochin susceptibility helps identify pneumococci. Bile esculin hydrolysis helps identify enterococci and group D streptococci."}];
